func TestZZScratchRoutable(t *testing.T) {
	type route struct {
		method string
		path   string
	}
	routes := []route{
		{http.MethodGet, "/"},
		{http.MethodGet, "/users/:id"},
		{http.MethodGet, "/users/:id/posts"},
		{http.MethodGet, "/static/*"},
		{http.MethodPost, "/only-post"},
		{http.MethodGet, "/a/:b/c/:d"},
	}

	paths := []string{
		"",
		"noslash",
		"/",
		"//",
		"///",
		"/users",
		"/users/",
		"/users//",
		"/users/1",
		"/users/1/",
		"/users/1//",
		"/users/1/posts",
		"/users/1/posts/",
		"/users/1/posts/2",
		"/static",
		"/static/",
		"/static/a",
		"/static/a/b",
		"/only-post",
		"/only-post/",
		"/nope",
		"/a/1/c/2",
		"/a/1/c/",
		"/a/1/c",
		"/:",
		"*",
		"/users/:id",
		"/users/*",
		"/USERS/1",
		"/users/1/posts/x/y",
	}

	for _, rt := range routes {
		e := New()
		e.GET("/", func(c Context) error { return c.String(http.StatusOK, "root") })
		e.GET("/users/:id", func(c Context) error { return c.String(http.StatusOK, "user") })
		e.GET("/users/:id/posts", func(c Context) error { return c.String(http.StatusOK, "posts") })
		e.GET("/static/*", func(c Context) error { return c.String(http.StatusOK, "static") })
		e.POST("/only-post", func(c Context) error { return c.String(http.StatusOK, "onlypost") })
		e.GET("/a/:b/c/:d", func(c Context) error { return c.String(http.StatusOK, "abcd") })

		// direct Find
		for _, p := range paths {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						fmt.Printf("PANIC  Find  %-6s %-22q => %v\n", rt.method, p, rec)
					}
				}()
				c := e.NewContext(httptest.NewRequest(rt.method, "/", nil), httptest.NewRecorder())
				e.Router().Find(rt.method, p, c)
				fmt.Printf("OK     Find  %-6s %-22q => path=%q pnames=%v handler=%p\n", rt.method, p, c.Path(), c.ParamNames(), c.Handler())
			}()
		}

		// via ServeHTTP
		for _, p := range paths {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						fmt.Printf("PANIC  HTTP  %-6s %-22q => %v\n", rt.method, p, rec)
					}
				}()
				req := httptest.NewRequest(rt.method, "http://example.com"+p, nil)
				req.URL.Path = p // keep raw value, no cleaning
				req.URL.RawPath = ""
				rec := httptest.NewRecorder()
				e.ServeHTTP(rec, req)
				fmt.Printf("OK     HTTP  %-6s %-22q => status=%d body=%q\n", rt.method, p, rec.Code, rec.Body.String())
			}()
		}
	}
}

