package echo

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"runtime/debug"
	"testing"
	"time"
)

func zzRunFind(e *Echo, method, p string) (res string) {
	done := make(chan string, 1)
	go func() {
		defer func() {
			if rec := recover(); rec != nil {
				done <- fmt.Sprintf("PANIC: %v\n%s", rec, debug.Stack())
			}
		}()
		c := e.NewContext(httptest.NewRequest(method, "/", nil), httptest.NewRecorder())
		e.Router().Find(method, p, c)
		done <- fmt.Sprintf("ok path=%q pnames=%v params=%v", c.Path(), c.ParamNames(), c.ParamValues())
	}()
	select {
	case r := <-done:
		return r
	case <-time.After(300 * time.Millisecond):
		return "HANG (timeout 300ms)"
	}
}

