		case 0:
			segs = append(segs, "a")
		case 1:
			segs = append(segs, "b")
		case 2:
			segs = append(segs, "ab")
		case 3:
			segs = append(segs, ":p")
		case 4:
			segs = append(segs, "*")
		case 5:
			segs = append(segs, "c")
		}
	}
	return "/" + strings.Join(segs, "/")
}

