func TestZZDiff(t *testing.T) {
	seen := map[string]bool{}
	nDiff := 0
	for seed := int64(0); seed < 30000; seed++ {
		rnd := rand.New(rand.NewSource(seed))
		e := New()
		nr := rnd.Intn(5) + 1
		rs := []string{}
		for i := 0; i < nr; i++ {
			rp := zzGenRoute3(rnd)
			rs = append(rs, rp)
			e.GET(rp, func(c Context) error { return nil })
		}
		for i := 0; i < 30; i++ {
			p := zzGenPath3(rnd)
			c := e.NewContext(nil, nil)
			e.Router().Find(http.MethodGet, p, c)
			gotPath := c.Path()
			gotVals := c.ParamValues()
			gotNames := c.ParamNames()

			expPath, expVals, ok := zzRefFind(e.Router().tree, p)
			if !ok {
				expPath = ""
				expVals = nil
			}
			if gotPath != expPath {
				key := fmt.Sprintf("ROUTE-MISMATCH routes=%v path=%q got=%q want=%q", rs, p, gotPath, expPath)
				if !seen[key] {
					seen[key] = true
					nDiff++
					if nDiff < 25 {
						fmt.Println(key)
					}
				}
				continue
			}
			if expPath != "" {
				// compare param values
				if len(gotNames) != len(expVals) {
					key := fmt.Sprintf("NAMES-MISMATCH routes=%v path=%q got=%v want=%v", rs, p, gotNames, expVals)
					if !seen[key] {
						seen[key] = true
						nDiff++
						if nDiff < 25 {
							fmt.Println(key)
						}
					}
					continue
				}
				for j := range expVals {
					if j < len(gotVals) && gotVals[j] != expVals[j] {
						key := fmt.Sprintf("VAL-MISMATCH routes=%v path=%q names=%v got=%v want=%v", rs, p, gotNames, gotVals, expVals)
						if !seen[key] {
							seen[key] = true
							nDiff++
							if nDiff < 25 {
								fmt.Println(key)
							}
						}
					}
				}
			}
		}
	}
	fmt.Println("diff done, distinct mismatches:", nDiff)
}
