package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

// reference matcher: DFS with priority static > param > any
func zzRef(n *node, search string, vals []string) (string, []string, bool) {
	if search == "" && n.ppath != "" {
		return n.ppath, vals, true
	}
	for _, c := range n.staticChildren {
		if strings.HasPrefix(search, c.prefix) {
			if p, v, ok := zzRef(c, search[len(c.prefix):], vals); ok {
				return p, v, true
			}
		}
	}
	if n.paramChild != nil && search != "" {
		i := strings.IndexByte(search, '/')
		if i < 0 {
			i = len(search)
		}
		nv := append(append([]string{}, vals...), search[:i])
		if p, v, ok := zzRef(n.paramChild, search[i:], nv); ok {
			return p, v, true
		}
	}
	if n.anyChild != nil && n.anyChild.ppath != "" {
		return n.anyChild.ppath, append(append([]string{}, vals...), search), true
	}
	return "", nil, false
}

func zzRefFind(root *node, path string) (string, []string, bool) {
	if !strings.HasPrefix(path, root.prefix) {
		return "", nil, false
	}
	return zzRef(root, path[len(root.prefix):], nil)
}

func zzGenRoute3(rnd *rand.Rand) string {
	n := rnd.Intn(5) + 1
	segs := []string{}
	for i := 0; i < n; i++ {
		switch rnd.Intn(7) {
		case 0:
			segs = append(segs, "a")
		case 1:
			segs = append(segs, "b")
		case 2:
			segs = append(segs, "ab")
		case 3:
			segs = append(segs, ":p")
		case 4:
			segs = append(segs, "*")
		case 5:
			segs = append(segs, "")
		case 6:
			segs = append(segs, "abc")
		}
	}
	p := "/" + strings.Join(segs, "/")
	if rnd.Intn(6) == 0 {
		p += "/"
	}
	return p
}

func zzGenPath3(rnd *rand.Rand) string {
	alphabet := []string{"/", "a", "b", ":", "*", "ab", "c", "", "abc", "p"}
	n := rnd.Intn(12)
	var sb strings.Builder
	for i := 0; i < n; i++ {
		sb.WriteString(alphabet[rnd.Intn(len(alphabet))])
	}
	return sb.String()
}

func TestZZDiff(t *testing.T) {
	seen := map[string]bool{}
	nDiff := 0
	for seed := int64(0); seed < 30000; seed++ {
		rnd := rand.New(rand.NewSource(seed))
		e := New()
		nr := rnd.Intn(5) + 1
		rs := []string{}
		for i := 0; i < nr; i++ {
			rp := zzGenRoute3(rnd)
			rs = append(rs, rp)
			rp := rp
			e.GET(rp, func(c Context) error {
				c.Set("route", rp)
				return nil
			})
		}
		for i := 0; i < 30; i++ {
			p := zzGenPath3(rnd)
			c := e.NewContext(nil, nil)
			e.Router().Find(http.MethodGet, p, c)
			gotRoute := ""
			if err := c.Handler()(c); err == nil {
				if v := c.Get("route"); v != nil {
					gotRoute = v.(string)
				}
			}
			expPath, expVals, ok := zzRefFind(e.Router().tree, p)
			if !ok {
				expPath = ""
			}
			if gotRoute != expPath {
				key := fmt.Sprintf("MISMATCH routes=%v path=%q got=%q want=%q", rs, p, gotRoute, expPath)
				if !seen[key] {
					seen[key] = true
					nDiff++
					if nDiff < 20 {
						fmt.Println(key)
					}
				}
				continue
			}
			if ok {
				gotVals := c.ParamValues()
				gotNames := c.ParamNames()
				if len(gotNames) != len(expVals) {
					key := fmt.Sprintf("NAMES-MISMATCH routes=%v path=%q got=%v want=%v", rs, p, gotNames, expVals)
					if !seen[key] {
						seen[key] = true
						nDiff++
						if nDiff < 20 {
							fmt.Println(key)
						}
					}
					continue
				}
				for j := range expVals {
					if j < len(gotVals) && gotVals[j] != expVals[j] {
						key := fmt.Sprintf("VAL-MISMATCH routes=%v path=%q names=%v got=%v want=%v", rs, p, gotNames, gotVals, expVals)
						if !seen[key] {
							seen[key] = true
							nDiff++
							if nDiff < 20 {
								fmt.Println(key)
							}
						}
					}
				}
			}
		}
	}
	fmt.Println("diff done, distinct mismatches:", nDiff)
}
EOF
