func zzTryBig(e *Echo, method, p string) (res string) {
	done := make(chan string, 1)
	go func() {
		defer func() {
			if rec := recover(); rec != nil {
				lines := strings.Split(string(debug.Stack()), "\n")
				out := []string{}
				for _, l := range lines {
					if strings.Contains(l, "router.go") {
						out = append(out, strings.TrimSpace(l))
					}
				}
				if len(out) > 3 {
					out = out[:3]
				}
				done <- fmt.Sprintf("PANIC %v | %s", rec, strings.Join(out, " ;; "))
			}
		}()
		c := e.NewContext(nil, nil)
		e.Router().Find(method, p, c)
		done <- fmt.Sprintf("ok route=%q", c.Path())
	}()
	select {
	case r := <-done:
		return r
	case <-time.After(500 * time.Millisecond):
		return "HANG"
	}
}

