func zzShow(t *testing.T, name string, rec *httptest.ResponseRecorder) {
	t.Logf("CASE %s: status=%d headers=%v bodyLen=%d body=%q", name, rec.Code, rec.Header(), rec.Body.Len(), rec.Body.String())
}

func zzReq(t *testing.T, e *echo.Echo, name string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	req.Header.Set(echo.HeaderAcceptEncoding, "gzip")
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	zzShow(t, name, rec)
	return rec
}

func TestZZScratchGzipEmpty(t *testing.T) {
	e := echo.New()
	e.Use(Gzip())
	e.GET("/", func(c echo.Context) error { return nil })

	rec := zzReq(t, e, "a-empty-nil")
	if rec.Code != 200 {
		t.Errorf("a: status = %d, want 200", rec.Code)
	}
	if ce := rec.Header().Get(echo.HeaderContentEncoding); ce != "" {
		t.Errorf("a: Content-Encoding = %q, want empty", ce)
	}
	if rec.Body.Len() != 0 {
		t.Errorf("a: body = %q, want empty", rec.Body.String())
	}
}

func TestZZScratchGzipNoContent(t *testing.T) {
	e := echo.New()
	e.Use(Gzip())
	e.GET("/", func(c echo.Context) error { return c.NoContent(http.StatusNoContent) })
	rec := zzReq(t, e, "b-nocontent")
	if rec.Code != 204 {
		t.Errorf("b: status = %d, want 204", rec.Code)
	}
	if ce := rec.Header().Get(echo.HeaderContentEncoding); ce != "" {
		t.Errorf("b: Content-Encoding = %q, want empty", ce)
	}
	if rec.Body.Len() != 0 {
		t.Errorf("b: body = %q, want empty", rec.Body.String())
	}
}

func TestZZScratchGzipBody(t *testing.T) {
	e := echo.New()
	e.Use(Gzip())
	e.GET("/", func(c echo.Context) error { return c.String(http.StatusOK, "hello world") })
	rec := zzReq(t, e, "c-body")
	if ce := rec.Header().Get(echo.HeaderContentEncoding); ce != "gzip" {
		t.Errorf("c: Content-Encoding = %q, want gzip", ce)
	}
	r, err := gzip.NewReader(bytes.NewReader(rec.Body.Bytes()))
